Bước 2: tạo <code>process.php</code> xử lý dữ liệu nhận được.<pre><code>&lt;?php
// Ví dụ 5.6. Kiểm tra đã có dữ liệu POST chưa
if (isset($_POST["so_thu_nhat"]) &amp;&amp; isset($_POST["so_thu_hai"])) {
    $so_thu_nhat = $_POST["so_thu_nhat"];
    $so_thu_hai = $_POST["so_thu_hai"];
    // Kiểm tra tính hợp lệ của dữ liệu
    if (is_numeric($so_thu_nhat) &amp;&amp; is_numeric($so_thu_hai)) {
        $tong = $so_thu_nhat + $so_thu_hai;
        echo "&lt;h2&gt;Kết quả:&lt;/h2&gt;";
        echo "Tổng của $so_thu_nhat và $so_thu_hai là: $tong";
    } else {
        echo "Vui lòng nhập hai số hợp lệ.";
    }
} else {
    echo "Yêu cầu không hợp lệ.";
}
?&gt;</code></pre>

Tập tin <code>sach.php</code>: lấy thể loại để đổ vào <code>select</code>, rồi xử lý <code>$_GET</code>.<pre><code>&lt;?php
require_once "config.php";
$result = $conn-&gt;query("SELECT * FROM the_loai");
$theloai = $result ? $result-&gt;fetch_all(MYSQLI_ASSOC) : [];
?&gt;
&lt;form action="sach.php" method="get"&gt;
    Chọn thể loại:&lt;br&gt;
    &lt;select name="the_loai_sach"&gt;
    &lt;?php foreach ($theloai as $row) { ?&gt;
        &lt;option value="&lt;?php echo $row['id']; ?&gt;"&gt;
            &lt;?php echo $row["ten_the_loai"]; ?&gt;
        &lt;/option&gt;
    &lt;?php } ?&gt;
    &lt;/select&gt;
    &lt;input type="submit" value="Xem"&gt;
&lt;/form&gt;
&lt;?php
if (isset($_GET["the_loai_sach"])) {
    $the_loai = (int)$_GET["the_loai_sach"];
    $sql = "SELECT tieu_de, tac_gia FROM sach WHERE id_the_loai = " . $the_loai;
    $result = $conn-&gt;query($sql);
    if ($result) {
        $sach = $result-&gt;fetch_all(MYSQLI_ASSOC);
        echo "&lt;table class='book-table'&gt;&lt;thead&gt;&lt;th&gt;STT&lt;/th&gt;&lt;th&gt;Tên sách&lt;/th&gt;&lt;th&gt;Tác giả&lt;/th&gt;&lt;/thead&gt;&lt;tbody&gt;";
        foreach ($sach as $key =&gt; $row) {
            echo "&lt;tr&gt;&lt;td&gt;" . ($key + 1) . "&lt;/td&gt;&lt;td&gt;" . $row["tieu_de"] . "&lt;/td&gt;&lt;td&gt;" . $row["tac_gia"] . "&lt;/td&gt;&lt;/tr&gt;";
        }
        echo "&lt;/tbody&gt;&lt;/table&gt;";
    }
}
$conn-&gt;close();
?&gt;</code></pre>
